// ---------- Gates ----------
var GATE_FN={AND:function(a){return a.every(function(x){return x===1;})?1:0;},OR:function(a){return a.some(function(x){return x===1;})?1:0;},XOR:function(a){return a.reduce(function(p,x){return p^x;},0);},NAND:function(a){return 1-GATE_FN.AND(a);},NOR:function(a){return 1-GATE_FN.OR(a);},XNOR:function(a){return 1-GATE_FN.XOR(a);},NOT:function(a){return 1-a[0];},BUF:function(a){return a[0];}};
