  var k=primes.length;for(var size=1;size<=Math.min(k,6)&&!sols.length;size+=1){(function rec(start,chosen){if(chosen.length===size){if(ones.every(function(m){return chosen.some(function(i){return implicantCovers(primes[i],m);});})){var lits=chosen.reduce(function(a,i){return a+litCount(primes[i]);},0);if(bestCost===null||lits<bestCost){bestCost=lits;sols=[chosen.slice()];}else if(lits===bestCost)sols.push(chosen.slice());}return;}for(var i=start;i<k;i+=1){chosen.push(i);rec(i+1,chosen);chosen.pop();}})(0,[]);}
