function expectedText(fields){return fields.map(function(f){var shown=f.answer;if(f.options){var o=f.options.find(function(x){return x.value===String(f.answer);});if(o)shown=displayValue(o.label);}return(f.label?f.label+": ":"")+shown;}).join("; ");}
function generateQuestion(familyId,level,seed){var family=familyById(familyId),safeLevel=supportedLevel(family,level),data=scenario(family.id,safeLevel,new Rng(seed));if(!data)throw new Error("Missing digital-logic scenario: "+family.id);shuffleCandidateFields(data.fields,new Rng((Number(seed)^0x5BD1E995)>>>0));var fields=data.fields,canonical=canonicalFromFields(fields),expected=expectedText(fields),explanation=family.learn.rules+" "+(data.explanation?String(data.explanation).trim()+" ":"")+t("generated.explanationLead","The exact answer is")+" "+expected+".",tables=data.blocks.filter(function(block){return block.kind==="table";}),codeTexts=data.blocks.filter(function(block){return block.kind==="code";}).map(function(block){return block.text;}),semanticSignature=JSON.stringify({blocks:data.blocks,fields:fields.map(function(f){return{kind:f.kind,answer:f.answer,options:(f.options||[]).map(function(o){return o.value;})};})}),metadata=Object.assign({modelId:MODEL_ID,oracleVersion:ORACLE_VERSION,circuitModel:{type:"SemanticDigitalScenario",familyId:family.id,sourceBlocks:codeTexts.slice()},modelState:{tables:tables.map(function(block){return{caption:block.caption,columns:block.columns.slice(),rows:block.rows.map(function(row){return row.slice();})};}),offline:true,realExecution:false},expectedResult:canonical,difficultyDimensions:["level-"+safeLevel,family.categoryId],misconceptionsTargeted:[family.id],distractorProvenance:fields.flatMap(function(f){return(f.options||[]).filter(function(o){return o.value!==String(f.answer);}).map(function(o){return o.value;});}),workedTrace:explanation,structuralSignature:semanticSignature},data.meta||{});return{familyId:family.id,categoryId:family.categoryId,level:safeLevel,prompt:{title:data.title,blocks:data.blocks,note:data.note},fields:fields,canonicalAnswer:canonical,expectedText:expected,explanation:explanation,structuralSignature:family.id+":"+semanticSignature,metadata:metadata};}
